Implementation:
```csharp
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainerService
{
    public static void TrainAndSaveModel(string dataPath, string modelPath)
    {
        var mlContext = new MLContext(seed: 42);

        IDataView data = mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = mlContext.Transforms.CustomMapping<TicketData, CombinedText>(
                (input, output) => output.Text = $"{input.Subject} {input.Description}", contractName: null)
            .Append(mlContext.Transforms.Text.FeaturizeText("TextFeatures", nameof(CombinedText.Text)))
            .Append(mlContext.Transforms.Concatenate("Features", "TextFeatures", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        Console.WriteLine("=== Model Evaluation Metrics ===");
        Console.WriteLine($"MacroAccuracy:  {metrics.MacroAccuracy:F4}");
        Console.WriteLine($"MicroAccuracy:  {metrics.MicroAccuracy:F4}");
        Console.WriteLine($"LogLoss:        {metrics.LogLoss:F4}");
        Console.WriteLine($"LogLossReduction: {metrics.LogLossReduction:F4}");
        Console.WriteLine();
        Console.WriteLine("Per-class metrics:");
        Console.WriteLine($"{"Class",-15} {"Precision",10} {"Recall",10} {"F1Score",10}");
        for (int i = 0; i < metrics.PerClassLogLoss.Count; i++)
        {
            Console.WriteLine($"Class {i,-10} {metrics.PerClassLogLoss[i],10:F4}");
        }
        Console.WriteLine("================================");

        mlContext.Model.Save(model, data.Schema, modelPath);
        Console.WriteLine($"Model saved to {modelPath}");
    }
}

